INSERT INTO AF_CATALOG (DATA) SELECT PARSE_JSON($${"value_props":[{"id":"VP-ONE-SCHEDULE","text":"One schedule for every technician cuts drive time and overtime","themes":["cost","consolidation"]},{"id":"VP-DISPATCH-CONNECT","text":"Dispatch Connect syncs job status both ways; your dispatch system stays the system of record","themes":["integration"]},{"id":"VP-REPLACE","text":"Scheduling, dispatch sync and job notes in one platform, with named tools retired","themes":["consolidation"]},{"id":"VP-SCALE","text":"Scale scheduling from one division to many without new tools","themes":["growth"]}],"proof_points":[{"id":"PP-BLUEPEAK","text":"Bluepeak Utilities (fictional): overtime down 18% in two quarters after moving 600 technicians to one schedule."},{"id":"PP-BLUEPEAK3","text":"Bluepeak Utilities (fictional): retired three field tools in one quarter."},{"id":"PP-HARROW","text":"Harrow Lifts (fictional): connected to their dispatch system and live across 4 regions in 9 weeks."}]}$$);

MERGE INTO AF_CONFIG t USING (SELECT f.key AS K, f.value::STRING AS V FROM TABLE(FLATTEN(INPUT => PARSE_JSON($${"demo_today":"2026-11-09","owner":"{\"id\": \"005ORB000000001AAA\", \"name\": \"Alex Rivera\", \"email\": \"ae@acme.example\", \"slack_handle\": \"alex.rivera\"}","seller":"{\"company\": \"Acme\", \"domain\": \"acme.example\"}","model":"scripted","cortex_model":"mistral-large2","brief_size":"5","max_per_motion":"3","cooldown_days":"14","snooze_days":"3","min_confidence":"50","scoring_version":"af_v1.0"}$$))) f) s
  ON t.K = s.K WHEN MATCHED THEN UPDATE SET V = s.V WHEN NOT MATCHED THEN INSERT (K, V) VALUES (s.K, s.V);
